import { Table, BooleanColumn, GenericColumn } from '../../db'

export const sc_cat_item_guide = Table({
    allowWebServiceAccess: true,
    attributes: {
        synch_attachments: true,
        update_synch: true,
    },
    extends: 'sc_cat_item',
    label: 'Order guide',
    name: 'sc_cat_item_guide',
    schema: {
        cascade: BooleanColumn({
            default: false,
            label: 'Cascade Variables',
        }),
        two_step: BooleanColumn({
            default: false,
            label: 'Two step',
        }),
        include_items: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'To Show/Hide the Include Toggle on items in Order Guide widget (Service Portal)',
                    label: 'Show Include Toggle',
                    plural: 'Show Include Toggles',
                },
            ],
        }),
        script: GenericColumn({
            attributes: {
                no_text_index: true,
            },
            columnType: 'script_plain',
            label: 'Script',
            maxLength: 8000,
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        validator: GenericColumn({
            attributes: {
                no_text_index: true,
            },
            columnType: 'script_plain',
            label: 'Validator',
            maxLength: 8000,
        }),
        order_to_cart: BooleanColumn({
            default: false,
            label: 'Order to cart',
        }),
    },
    textIndex: true,
})
